<template><el-container><el-header><el-button @click="router.push('/health-home')">返回首页</el-button><h3>健康师工作台</h3></el-header><el-main><el-alert title="仅可访问已分配给本健康师的患者" type="info" :closable="false"/><el-select v-model="userId" placeholder="选择患者" @change="load"><el-option v-for="p in patients" :key="p.id" :value="p.user_id" :label="p.real_name"/></el-select><el-button v-if="userId" @click="router.push({path:'/health-records/medichine',query:{userId}})">患者用药记录</el-button><el-button v-if="userId" @click="router.push({path:'/health-records/record',query:{userId}})">患者随访记录</el-button><el-button v-if="userId" @click="router.push({path:'/health-records/up',query:{userId}})">患者异常预警</el-button><el-button @click="router.push('/health-consultation')">问询队列</el-button><el-card v-for="r in reports" :key="r.id"><h3>{{r.title}} · {{r.status}}</h3><el-tag>{{r.source}}</el-tag><el-input v-model="r.content" type="textarea" :rows="10"/><el-button type="primary" @click="review(r)">保存并审批确认</el-button></el-card><el-empty v-if="!reports.length" description="暂无报告"/></el-main></el-container></template>
<script setup>import {ref,onMounted}from'vue';import{useRouter}from'vue-router';import{call}from'@/api/health';import{ElMessage}from'element-plus';const router=useRouter(),patients=ref([]),userId=ref(),reports=ref([]);async function load(){reports.value=(await call('workflow/reports','get',null,{userId:userId.value})).data}async function review(r){await call('workflow/report/'+r.id+'/review','post',{content:r.content});ElMessage.success('已审批确认');load()}onMounted(async()=>{patients.value=(await call('workflow/patients')).data})</script><style scoped>.el-header{display:flex;gap:24px;align-items:center}.el-main{background:#f1f7f6;min-height:90vh;padding:32px}.el-card{margin-top:24px}</style>
